def f(g):
    H=len(g); W=len(g[0]); out=[[0]*W for _ in range(H)]
    for c in range(W):
        col=[g[r][c] for r in range(H) if g[r][c]]
        r=H-1
        for v in reversed(col):
            while r>=0 and out[r][c]!=0: r-=1
            r-=1
            if r>=0: out[r][c]=v
    return out

