from collections import deque
def solve(inp, horiz=False):
    h=len(inp); w=len(inp[0])
    cells={i:{j:(inp[i][j]==2) for j in range(w)} for i in range(h)}
    # collect components of non-0, non-2 cells
    seen=set(); objs=[]
    for i in range(h):
        for j in range(w):
            if inp[i][j]!=0 and inp[i][j]!=2 and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); comp=[(i,j)]
                while q:
                    r,c=q.popleft()
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and inp[nr][nc]!=0 and inp[nr][nc]!=2 and (nr,nc) not in seen:
                            seen.add((nr,nc)); q.append((nr,nc)); comp.append((nr,nc))
                objs.append(set(comp))
    # direction: towards the 2-line
    dirs = {}
